import os

import yaml
from launch import LaunchDescription
from launch_ros.actions import Node

THIS_DIR = os.path.dirname(os.path.abspath(__file__))
BASE_DIR = os.path.dirname(THIS_DIR)
URDF_PATH = os.path.join(BASE_DIR, "urdf", "arm.urdf")
CONFIG_DIR = os.path.join(BASE_DIR, "config")
SRDF_PATH = os.path.join(CONFIG_DIR, "arm.srdf")
ROS2_CONTROLLERS_PATH = os.path.join(CONFIG_DIR, "ros2_controllers.yaml")


def load_file(path):
    with open(path, "r") as f:
        return f.read()


def load_yaml(path):
    with open(path, "r") as f:
        return yaml.safe_load(f)


def generate_launch_description():
    robot_description = {"robot_description": load_file(URDF_PATH)}
    robot_description_semantic = {
        "robot_description_semantic": load_file(SRDF_PATH)
    }
    robot_description_kinematics = {
        "robot_description_kinematics": load_yaml(
            os.path.join(CONFIG_DIR, "kinematics.yaml")
        )
    }
    robot_description_planning = {
        "robot_description_planning": load_yaml(
            os.path.join(CONFIG_DIR, "joint_limits.yaml")
        )
    }

    ompl_config = load_yaml(os.path.join(CONFIG_DIR, "ompl_planning.yaml"))
    planning_pipelines = {
        "planning_pipelines": ["ompl"],
        "default_planning_pipeline": "ompl",
        "ompl": ompl_config,
    }

    trajectory_execution = {"moveit_manage_controllers": True}
    trajectory_execution.update(
        load_yaml(os.path.join(CONFIG_DIR, "moveit_controllers.yaml"))
    )

    planning_scene_monitor = {
        "publish_planning_scene": True,
        "publish_geometry_updates": True,
        "publish_state_updates": True,
        "publish_transforms_updates": True,
    }

    move_group_capabilities = {"capabilities": "", "disable_capabilities": ""}

    move_group_params = [
        robot_description,
        robot_description_semantic,
        robot_description_kinematics,
        robot_description_planning,
        planning_pipelines,
        trajectory_execution,
        planning_scene_monitor,
        move_group_capabilities,
        {
            "publish_robot_description_semantic": True,
            "allow_trajectory_execution": True,
        },
    ]

    rsp_node = Node(
        package="robot_state_publisher",
        executable="robot_state_publisher",
        output="screen",
        parameters=[robot_description],
    )

    ros2_control_node = Node(
        package="controller_manager",
        executable="ros2_control_node",
        output="screen",
        parameters=[ROS2_CONTROLLERS_PATH],
        remappings=[("/controller_manager/robot_description", "/robot_description")],
    )

    joint_state_broadcaster_spawner = Node(
        package="controller_manager",
        executable="spawner",
        arguments=["joint_state_broadcaster"],
        output="screen",
    )

    arm_controller_spawner = Node(
        package="controller_manager",
        executable="spawner",
        arguments=["arm_controller"],
        output="screen",
    )

    move_group_node = Node(
        package="moveit_ros_move_group",
        executable="move_group",
        output="screen",
        parameters=move_group_params,
    )

    return LaunchDescription(
        [
            rsp_node,
            ros2_control_node,
            joint_state_broadcaster_spawner,
            arm_controller_spawner,
            move_group_node,
        ]
    )

